use verus::prelude::*;

// A pure/spec function that counts how many `true` values
// occur in the boolean sequence `b[0..n]`.  We need a decreases
// clause so that the recursion is justified.
#[verifier::spec]
#[verifier::decreases(n)]
fn count_true(b: Seq<bool>, n: nat) -> nat {
    if n == 0 {
        0
    } else {
        // recurse on n-1, then add 1 if the last element is true
        count_true(b, n - 1) + if b[n - 1] { 1 } else { 0 }
    }
}

