fn place(arr: Vec<f32>, mask: Vec<bool>, vals: Vec<f32>) -> Vec<f32> {
    // Prepare the result vector with the same capacity as the input
    let mut result = Vec::with_capacity(arr.len());
    // Index into vals, will cycle using modulo
    let mut val_idx = 0;

    // Walk through arr and mask in lockstep
    for (a, &m) in arr.iter().zip(mask.iter()) {
        if m {
            // Use the next replacement value, cycling when we reach the end
            result.push(vals[val_idx]);
            val_idx = (val_idx + 1) % vals.len();
        } else {
            // Keep the original element
            result.push(*a);
        }
    }

    result
}

